finishButton.onclick=async()=>{const s=session();if(s.completedAt){try{await globalThis.milaiAccess.finish(s);toast('הספירה הסתיימה. אפשר לצפות, לגבות ולייצא')}catch(e){toast(e.message)}return}if(!globalThis.milaiAccess?.canWrite(s)){toast('הרישיון אינו מאפשר סיום של הספירה הזאת');return}if(!confirm(`לסיים את הספירה „${s.name}” ובה ${Object.keys(s.items).length} מוצרים? לאחר האישור היא תישאר לצפייה ולייצוא בלבד. סריקות ותיקונים נוספים לא יתאפשרו במחזור הזה.`))return;if(await mutate(()=>{s.completedAt=Date.now()})){try{await globalThis.milaiAccess.finish(s);toast('הספירה הסתיימה ונשמרה במכשיר')}catch(e){toast('הספירה נשמרה כסגורה. אישור הסיום טרם סונכרן: '+e.message)}render()}};
